-- ImGui module resolution: use the versioned v0.9 object passed via _G from tbc.lua,
-- or fall back to a reaper["ImGui_*"] metatable proxy for standalone/console loading.
-- This ensures ImGui.DrawList_AddLine() etc. never throw nil index errors.
local ImGui = _G.ImGui or setmetatable({}, {
  __index = function(_, k) return reaper["ImGui_" .. k] end
})

