--
-- PTS_SPECTRUM:     N_BINS/FINE_STEP = 128 points = 256 slots (loop is deterministic)
-- PTS_TARGET_*:     N_BINS/CORRIDOR_STEP = 64 points = 128 slots
-- PTS_PROBE_SPECTRUM: always 256 points = 512 slots
local function _new_pts(n_points)
  local t = {}; for i = 1, n_points * 2 do t[i] = 0.0 end
  return reaper.new_array(t)
end
local PTS_SPECTRUM        = _new_pts(N_BINS / FINE_STEP)        -- 128 pts, 256 slots
local PTS_TARGET_UPPER    = _new_pts(math.ceil(N_BINS / 4) + 1) -- 65 pts,  130 slots
local PTS_TARGET_LOWER    = _new_pts(math.ceil(N_BINS / 4) + 1) -- 65 pts,  130 slots
local PTS_PROBE_SPECTRUM  = _new_pts(N_BINS)                    -- 256 pts, 512 slots
-- Smoothing scratch buffer for 1/3-octave kernel
VIEW._smooth_scratch = {}
for i = 0, N_BINS - 1 do VIEW._smooth_scratch[i] = -70 end

VIEW._unmask_toast      = nil  -- Unmask success banner text
VIEW._unmask_toast_time = nil
VIEW._unmask_cooldown   = nil
VIEW._autofit_ref = nil   -- Resolved by tbc.lua after require
VIEW._bridge_ref        = nil   -- Set each frame by draw_fine

-- Spectral Collision Heatmap (Neutron 5 parity) pre-allocated buffers
-- Zero GC pressure: all arrays fixed-capacity at module load time.
VIEW._probe_bins           = {}  -- 256 raw dB from gmem[1200..1455]
VIEW._probe_smooth         = {}  -- 256 floats after 1/3-oct smoothing
VIEW._probe_norm           = {}  -- 256 normalized for relative comparison
VIEW._master_norm          = {}  -- 256 normalized master bins (shape-matched)
  -- PTS_PROBE_SPECTRUM allocated as module-level local above (512 slots, 256 x,y pairs)
for i = 1, 256 do
  VIEW._probe_bins[i]            = -90.0
  VIEW._probe_smooth[i]          = -90.0
  VIEW._probe_norm[i]            = -90.0
  VIEW._master_norm[i]           = -90.0
    -- _pts_probe_spectrum is reaper_array; pre-zeroed at allocation, no per-element init needed
end
