-- All math using the strict single formula: x = log10(f/20)/log10(1000)
-- This is the ONLY formula used for HzÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚ÂX and matches JSFX bin mapping.

local LOG_1000 = math.log(1000.0)
local LOG_20   = math.log(20.0)

function VIEW.freq_to_norm(f)
  if f <= 20 then return 0 end
  if f >= 20000 then return 1 end
  return (math.log(f) - LOG_20) / (math.log(20000) - LOG_20)
end

function VIEW.norm_to_freq(t)
  return 20.0 * math.exp(t * (math.log(20000) - LOG_20))
end

function VIEW.bin_to_norm(i)
  -- JSFX log-maps bins: freq = 20 * 1000^(i/255)
  return i / (N_BINS - 1)   -- 0..1
end

function VIEW.freq_to_x(f, x0, w)
  return x0 + VIEW.freq_to_norm(f) * w
end

function VIEW.db_to_y(db, y0, h, db_floor, db_ceil)
  -- Spec: Y(G) = y0 + [(G_disp_max - G) / (G_disp_max - G_disp_min)] * H
  -- Screen Y increases downward; db_ceil (high dB) maps to y0 (top).
  local norm = (db_ceil - db) / (db_ceil - db_floor)
  return y0 + math.max(0.0, math.min(1.0, norm)) * h
end

