-- Applied to raw gmem bins before rendering. Window widens at higher
-- frequencies (proportional to bin index) to match 1/3-oct behaviour.
-- Uses VIEW._smooth_scratch as in-place scratch (zero alloc).
function VIEW.smooth_spectrum(raw_bins, out_bins, window_oct)
  window_oct = window_oct or 0.333   -- default: 1/3 octave
  local N = N_BINS
  -- Convert octave window to bin window at each position
  for i = 0, N - 1 do
    -- Local frequency
    local f    = 20.0 * (1000.0 ^ (i / (N - 1)))
    local f_lo = f / (2 ^ (window_oct * 0.5))
    local f_hi = f * (2 ^ (window_oct * 0.5))
    -- Convert frequency bounds to bin indices (linear approx for small windows)
    local b_lo = math.max(0, math.floor((math.log(f_lo/20) / math.log(1000)) * (N-1)))
    local b_hi = math.min(N-1, math.ceil( (math.log(math.max(21,f_hi)/20) / math.log(1000)) * (N-1)))
    -- Triangular kernel weight
    local sum, wtotal = 0, 0
    for j = b_lo, b_hi do
      local w = 1.0 - math.abs(j - i) / math.max(1, b_hi - b_lo)
      local v = raw_bins[j] or -70
      if v > -90 then sum = sum + v * w; wtotal = wtotal + w end
    end
    VIEW._smooth_scratch[i] = (wtotal > 0) and (sum / wtotal) or (raw_bins[i] or -70)
  end
  -- Copy result into out_bins (in-place update, no new table)
  for i = 0, N - 1 do
    out_bins[i] = VIEW._smooth_scratch[i]
  end
end

