-- Anchors the display curve at 0 dB regardless of master fader level.
-- Reads mid-band mean (300 Hz..3 kHz ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¢ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬Ãƒâ€šÃ‚Â°ÃƒÆ’Ã¢â‚¬Â¹ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â  bins 90..175) as anchor.
-- Also applies pink-noise tilt correction per-bin.
-- pink_corr table is passed from TGT module (or nil to skip tilt).
function VIEW.normalize_for_display(bins, pink_corr, anchor_lufs)
  local MB_LO, MB_HI = 90, 175
  local sum, n = 0, 0
  for i = MB_LO, MB_HI do
    local v = (bins[i] or -70) + (pink_corr and pink_corr[i] or 0)
    if v > -90 then sum = sum + v; n = n + 1 end
  end
  local anchor = (n > 0) and (sum / n) or 0
  -- Optionally use LUFS to stabilize during level changes
  if anchor_lufs and anchor_lufs > -70 then
    anchor = anchor + (anchor_lufs + 14.0) * 0.3
  end
  -- Write tilt-corrected + anchored values back into the same buffer
  for i = 0, N_BINS - 1 do
    bins[i] = (bins[i] or -70) + (pink_corr and pink_corr[i] or 0) - anchor
  end
end

