local FREQ_GRID   = {20, 30, 50, 100, 200, 500, 1000, 2000, 5000, 10000, 20000}
local FREQ_LABELS = {"20", "30", "50", "100", "200", "500", "1k", "2k", "5k", "10k", "20k"}

function VIEW.draw_grid(dl, x0, y0, w, h, db_floor, db_ceil)
  ImGui.DrawList_AddRectFilled(dl, x0, y0, x0+w, y0+h, 0x0D1117FF, 6)
  ImGui.DrawList_AddRect(dl, x0, y0, x0+w, y0+h, C.border, 6)
  -- Frequency grid
  for i, f in ipairs(FREQ_GRID) do
    local gx = VIEW.freq_to_x(f, x0, w)
    ImGui.DrawList_AddLine(dl, gx, y0, gx, y0+h, C.grid_line, 1)
    ImGui.DrawList_AddText(dl, gx-8, y0+h+3, C.grid_label, FREQ_LABELS[i])
  end
  -- dB grid
  for db = db_floor, db_ceil, 6 do
    local gy = VIEW.db_to_y(db, y0, h, db_floor, db_ceil)
    local is_zero = (db == 0)
    ImGui.DrawList_AddLine(dl, x0, gy, x0+w, gy, is_zero and C.zero_line or C.grid_line, is_zero and 1 or 1)
    ImGui.DrawList_AddText(dl, x0-28, gy-6, C.grid_label, string.format("%+d", db))
  end
end

