-- Renders the upper/target/lower corridor from a 256-bin curve table.
-- Uses pre-allocated _pts_target_upper / _pts_target_lower buffers.
local CORRIDOR_STEP = 4   -- sample every 4th bin for corridor (perf)
function VIEW.draw_corridor(dl, x0, y0, w, h, db_floor, db_ceil, curve, scale)
  if not curve then return end
  local pu = PTS_TARGET_UPPER
  local pl = PTS_TARGET_LOWER
  local n  = 0
  for i = 0, N_BINS - 1, CORRIDOR_STEP do
    local f  = 20.0 * (1000.0 ^ (i / (N_BINS - 1)))
    local gx = VIEW.freq_to_x(f, x0, w)
    local sc = scale or VIEW.corridor_scale or 1.0
    local tgt = (curve.upper[i] or 0 + (curve.lower[i] or 0)) * 0.5
    local upper_sc = tgt + ((curve.upper[i] or 0) - tgt) * sc
    local lower_sc = tgt - (tgt - (curve.lower[i] or 0)) * sc
    local uy = VIEW.db_to_y(upper_sc, y0, h, db_floor, db_ceil)
    local ly = VIEW.db_to_y(lower_sc, y0, h, db_floor, db_ceil)
    n = n + 1
    pu[n*2-1] = gx; pu[n*2] = uy
    pl[n*2-1] = gx; pl[n*2] = ly
  end

  -- Filled corridor quads
  for i = 1, n - 1 do
    local xi   = pu[(i-1)*2+1]; local yu_i = pu[(i-1)*2+2]; local yl_i = pl[(i-1)*2+2]
    local xi1  = pu[i*2+1];     local yu_i1= pu[i*2+2];     local yl_i1= pl[i*2+2]
    ImGui.DrawList_AddQuadFilled(dl, xi, yu_i, xi1, yu_i1, xi1, yl_i1, xi, yl_i, C.corridor)
  end

  -- Target center spline (bezier segments)
  for i = 1, n - 1 do
    local xi  = pu[(i-1)*2+1]; local ui = pu[(i-1)*2+2]; local li = pl[(i-1)*2+2]
    local xi1 = pu[i*2+1];     local ui1= pu[i*2+2];     local li1= pl[i*2+2]
    local ty0 = (ui + li) * 0.5;  local ty1 = (ui1 + li1) * 0.5
    local cx1 = xi + (xi1 - xi) / 3
    local cx2 = xi + (xi1 - xi) * 2 / 3
    ImGui.DrawList_AddBezierCubic(dl, xi, ty0, cx1, ty0, cx2, ty1, xi1, ty1, C.target_line, 1.5)
  end
end

