-- Uses pre-allocated VIEW._pts_spectrum buffer.
function VIEW.draw_spectrum(dl, x0, y0, w, h, db_floor, db_ceil, bins, engine_alive)
  if not engine_alive then
    ImGui.DrawList_AddText(dl, x0+w/2-180, y0+h/2-8, C.warn,
      "[!] Engine offline -- insert Damei_TonalBalance.jsfx on any track.")
    return
  end
  local pts = PTS_SPECTRUM
  local n = 0
  for i = 0, N_BINS - 1, FINE_STEP do
    local f  = 20.0 * (1000.0 ^ (i / (N_BINS - 1)))
    local db = bins[i] or -70
    n = n + 1
    pts[n*2-1] = VIEW.freq_to_x(f, x0, w)
    pts[n*2]   = VIEW.db_to_y(db, y0, h, db_floor, db_ceil)
  end
  -- Filled area below curve (strip quads)
  local bot = y0 + h
  for i = 1, n - 1 do
    ImGui.DrawList_AddQuadFilled(dl,
      pts[(i-1)*2+1], pts[(i-1)*2+2],
      pts[i*2+1],     pts[i*2+2],
      pts[i*2+1],     bot,
      pts[(i-1)*2+1], bot,
      C.spectrum_fill)
  end
  -- Spectrum polyline (trim to actual n points)
      if n >= 2 then
    ImGui.DrawList_AddPolyline(dl, pts, C.spectrum, 0, 2.0)
  end
end

