local FINE_DB_FLOOR = -30
local FINE_DB_CEIL  =  18

-- ============================================================================
-- VIEW.draw_spectral_collision()
-- Neutron 5 parity Spectral Masking Heatmap + Ghost Spectrum Overlay
-- ============================================================================
-- Reads probe spectrum from gmem[1200..1455] (256 bins, Damei_SpectrumProbe.jsfx).
-- Normalizes both master and probe to mid-band anchor (300 Hz-3 kHz).
-- Renders:
--   Pass 1: Vertical coral-red heat ribbons where |delta| < threshold_db.
--   Pass 2: Semi-transparent ghost spectrum polyline of competing track.
-- Returns true when probe is alive and rendering occurred.
function VIEW.draw_spectral_collision(ctx, ImGui, dl, x0, y0, w, h,
                                      db_floor, db_ceil, display_bins,
                                      threshold_db)
  -- Staleness check: probe must have written within last 400ms
  local is_active = (reaper.gmem_read(1198) or 0) == 1
  local last_hb   = reaper.gmem_read(1199) or 0
  if not is_active or (reaper.time_precise() - last_hb) > 0.40 then
    return false
  end

  local thresh = threshold_db or 3.5
  local N      = N_BINS

  -- 1. Read 256 probe bins from gmem (in-place, no allocation)
  for i = 1, N do
    VIEW._probe_bins[i] = reaper.gmem_read(1200 + (i - 1)) or -90
  end

  -- 2. 1/3-octave smooth probe (reuse existing VIEW.smooth_spectrum)
  VIEW.smooth_spectrum(VIEW._probe_bins, VIEW._probe_smooth)

  -- 3. Normalize probe to mid-band anchor (300 Hz-3 kHz = bins ~90..175)
  local p_sum, p_cnt = 0.0, 0
  for i = 90, 175 do
    local v = VIEW._probe_smooth[i] or -90
    if v > -80 then p_sum = p_sum + v; p_cnt = p_cnt + 1 end
  end
  local p_anchor = p_cnt > 0 and (p_sum / p_cnt) or -24.0

  -- 4. Normalize master display_bins to same mid-band anchor
  local m_sum, m_cnt = 0.0, 0
  for i = 90, 175 do
    local v = display_bins[i-1] or -70   -- display_bins is 0-indexed
    if v > -80 then m_sum = m_sum + v; m_cnt = m_cnt + 1 end
  end
  local m_anchor = m_cnt > 0 and (m_sum / m_cnt) or -24.0

  for i = 1, N do
    -- Pink noise tilt compensation: +4.5 dB/octave boost toward high end
    local tilt = (math.log(math.max(i,1)) / math.log(2)) * 4.5
    VIEW._probe_norm[i]  = (VIEW._probe_smooth[i] - p_anchor) + tilt
    VIEW._master_norm[i] = (display_bins[i-1] or -70) - m_anchor + tilt
  end

