    if m_db > -24.0 and p_db > -24.0 then
      local delta = math.abs(m_db - p_db)
      if delta < thresh then
        local intensity = 1.0 - (delta / thresh)
        local heat      = intensity * intensity  -- quadratic falloff
        local xs = x0 + (i-1) * bin_w
        local xe = xs + bin_w + 0.5  -- 0.5px overlap eliminates sub-pixel gaps

        -- Main ribbon: 0x11 (faint glow) to 0x77 (full collision)
        local alpha    = math.floor(heat * 105)
        local col_rect = (0xF24B4B * 256) + (alpha % 256)
        ImGui.DrawList_AddRectFilled(dl, xs, y0, xe, y0+h, col_rect)

        -- Accent edge lines: top and bottom intensity markers
        local e_alpha  = math.floor(heat * 200)
        local col_edge = (0xF24B4B * 256) + (e_alpha % 256)
        ImGui.DrawList_AddLine(dl, xs, y0,   xe, y0,   col_edge, 2.0)
        ImGui.DrawList_AddLine(dl, xs, y0+h, xe, y0+h, col_edge, 2.0)

