-- Feature B: Multiband Phase Correlation Ribbon
function VIEW.draw_correlation_ribbon(dl, x0, ry, w)
  local alive = reaper.gmem_read(1059) or 0
  if alive == 0 then return end
  local rh = 5
  local FINE_STEP2 = 4
  for i = 0, N_BINS - 1, FINE_STEP2 do
    local r     = reaper.gmem_read(1060 + i) or 1.0
    r = math.max(-1.0, math.min(1.0, r))
    local f     = 20.0 * (1000.0 ^ (i / (N_BINS - 1)))
    local f2    = 20.0 * (1000.0 ^ (math.min(i + FINE_STEP2, N_BINS-1) / (N_BINS - 1)))
    local rx0   = VIEW.freq_to_x(f,  x0, w)
    local rx1   = VIEW.freq_to_x(f2, x0, w)
    local rr, gg, bb
    if r >= 0 then
      rr = math.floor(0xFB + r * (0x22 - 0xFB))
      gg = math.floor(0xBF + r * (0xD3 - 0xBF))
      bb = math.floor(0x24 + r * (0x99 - 0x24))
    else
      local ar = -r
      rr = math.floor(0xFB + ar * (0xEF - 0xFB))
      gg = math.floor(0xBF + ar * (0x44 - 0xBF))
      bb = math.floor(0x24 + ar * (0x44 - 0x24))
    end
    local col = ((rr * 65536 + gg * 256 + bb) * 256) + 0xCC
    ImGui.DrawList_AddRectFilled(dl, rx0, ry, rx1, ry + rh, col)
  end
end

-- Feature C: inst_B EQ Versus Mode diamond markers
function VIEW.draw_eq_curve_b(dl, x0, y0, w, h, db_floor, db_ceil, bands_b)
  if not bands_b or #bands_b == 0 then return end
  for _, band in ipairs(bands_b) do
    if band.enabled and band.freq and band.freq > 20 and math.abs(band.gain_db or 0) > 0.1 then
      local bx = VIEW.freq_to_x(band.freq, x0, w)
      local by = VIEW.db_to_y(band.gain_db or 0, y0, h, db_floor, db_ceil)
      local ds = 7
      ImGui.DrawList_AddQuad(dl, bx, by-ds, bx+ds, by, bx, by+ds, bx-ds, by, 0x22D3EEDD, 1.5)
    end
  end
end

-- Revised VIEW.draw_fine: Feature A masking + B ribbon + C versus + existing nodes
function VIEW.draw_fine(ctx, ImGui, dl, x0, y0, w, h, state, curve, bridge)
  VIEW.draw_grid(dl, x0, y0, w, h, FINE_DB_FLOOR, FINE_DB_CEIL)
  VIEW.draw_corridor(dl, x0, y0, w, h, FINE_DB_FLOOR, FINE_DB_CEIL, curve)
  if state.masking_overlay then
  -- Spectral Collision Heatmap (Neutron 5 parity)
  -- Compute VIEW._master_norm every frame (needed by AUTOFIT even when masking is off)
  -- Mid-band anchor: bins 90-175 (approx 300 Hz - 3 kHz)
  local _m_sum, _m_cnt = 0.0, 0
  for _i = 90, 175 do
    local _v = state.display_bins[_i-1] or -70
    if _v > -80 then _m_sum = _m_sum + _v; _m_cnt = _m_cnt + 1 end
  end
  local _m_anchor = _m_cnt > 0 and (_m_sum / _m_cnt) or -24.0
  for _i = 1, N_BINS do
    local _tilt = (math.log(math.max(_i,1)) / math.log(2)) * 4.5
    VIEW._master_norm[_i] = (state.display_bins[_i-1] or -70) - _m_anchor + _tilt
  end

  if state.masking_enabled then
    local has_probe = VIEW.draw_spectral_collision(
      ctx, ImGui, dl, x0, y0, w, h,
      FINE_DB_FLOOR, FINE_DB_CEIL,
      state.display_bins,
      state.masking_threshold or 3.5)
    state.probe_online = has_probe
  end
  end
  VIEW.draw_spectrum(dl, x0, y0, w, h, FINE_DB_FLOOR, FINE_DB_CEIL, state.display_bins, state.engine_alive)
  if state.show_corr_ribbon then
    VIEW.draw_correlation_ribbon(dl, x0, y0 + h - 8, w)
  end
  if state.versus_mode and bridge and bridge.bands_b then
    VIEW.draw_eq_curve_b(dl, x0, y0, w, h, FINE_DB_FLOOR, FINE_DB_CEIL, bridge.bands_b)
  end
  -- Store bridge ref for click-to-unmask dispatch from collision renderer
  if bridge then VIEW._bridge_ref = bridge end

  -- AUTOFIT band preview overlay: dashed hairlines when confirm is pending
  if state.autofit_bands and #state.autofit_bands > 0 then
    if VIEW._autofit_ref and VIEW._autofit_ref.draw_preview then
      VIEW._autofit_ref.draw_preview(ImGui, dl, x0, y0, w, h,
        FINE_DB_FLOOR, FINE_DB_CEIL, state.autofit_bands)
    end
  end

  if bridge and state.eq_visible and bridge.selected_inst then
    bridge.draw_nodes(ctx, ImGui, dl, x0, y0, w, h, FINE_DB_FLOOR, FINE_DB_CEIL)

  -- Unmask toast notification banner (2s auto-dismiss)
  if VIEW._unmask_toast and VIEW._unmask_toast_time then
    local age = reaper.time_precise() - VIEW._unmask_toast_time
    if age < 2.0 then
      local alpha = age < 1.6 and 220 or math.floor(220 * (1 - (age - 1.6) / 0.4))
      local toast_col = (0x22C55E * 256) + alpha  -- Green success toast
      local tw = #VIEW._unmask_toast * 7 + 16     -- approx text width
      local tx = x0 + (w - tw) * 0.5             -- centered
      local ty = y0 + h - 28
      ImGui.DrawList_AddRectFilled(dl, tx-8, ty-4, tx+tw, ty+18, (0x0A0F0A * 256) + alpha, 4)
      ImGui.DrawList_AddText(dl, tx, ty, toast_col, VIEW._unmask_toast)
    else
      VIEW._unmask_toast = nil  -- expire
    end
  end
  end

  -- =========================================================================
  -- P2: Alt+Drag Resonant Bandpass Sweep
  -- Hold Alt + drag horizontally inside spectrum canvas to sweep a biquad BPF.
  -- Center frequency mapped from cursor X using VIEW.freq_to_x inverse.
  -- Vertical drag maps to Q factor (0.5 near top => 12.0 near bottom).
  -- =========================================================================
  local is_alt = false; pcall(function() is_alt = ImGui.IsKeyDown(ctx, ImGui.Key_LeftAlt()) end)
  local is_mouse = ImGui.IsMouseDown(ctx, 0)
  local mx, my   = ImGui.GetMousePos(ctx)
  local in_canvas = mx >= x0 and mx < x0+w and my >= y0 and my < y0+h

  if is_alt and is_mouse and in_canvas then
    -- Map cursor X -> normalized frequency -> Hz
    local t_norm    = math.max(0, math.min(1, (mx - x0) / w))
    local sweep_hz  = VIEW.norm_to_freq(t_norm)
    -- Map cursor Y -> Q (top=high Q narrow, bottom=low Q wide)
    local q_norm    = math.max(0, math.min(1, (my - y0) / h))
    local sweep_q   = 0.5 + q_norm * 11.5   -- 0.5 .. 12.0
    -- Write to gmem for JSFX
    if _G.gmem_w then
      _G.gmem_w(474, sweep_hz)
      _G.gmem_w(475, sweep_q)
    end
    -- Visual: vertical cyan beam + frequency + Q label
    ImGui.DrawList_AddLine(dl, mx, y0, mx, y0+h, 0x00FFFFFF80, 1.5)
    ImGui.DrawList_AddLine(dl, mx-1, y0, mx-1, y0+h, 0x3DF3FF40, 3.0)
    local _fl = sweep_hz >= 1000 and string.format('%.2f kHz', sweep_hz/1000) or string.format('%.0f Hz', sweep_hz)
    local label = string.format('%s  Q %.1f', _fl, sweep_q)

    local lx = math.min(mx + 6, x0 + w - 100)
    ImGui.DrawList_AddRectFilled(dl, lx-2, y0+6, lx+92, y0+20, 0x000000BB, 3)
    ImGui.DrawList_AddText(dl, lx, y0+7, 0x3DF3FFFF, label)
    -- Diamond pip at top of beam
    ImGui.DrawList_AddCircleFilled(dl, mx, y0 + (q_norm * h), 4.0, 0xFFFFFFCC, 8)
  elseif not (is_alt and is_mouse) then
    -- Clear sweep when Alt released
    if _G.gmem_w then _G.gmem_w(474, 0) end
  end

  -- =========================================================================
  -- P4: EQ Bridge Band Overlays
  -- When BRIDGE is active and has bands, render draggable diamond handles
  -- at each band's (freq, gain) position. Drag vertically to adjust gain.
  -- =========================================================================
  if bridge and bridge.bands_b and #bridge.bands_b > 0 then
    for _, band in ipairs(bridge.bands_b) do
      local bx = VIEW.freq_to_x(band.freq_hz, x0, w)
      local by = VIEW.db_to_y(band.gain_db, y0, h, FINE_DB_FLOOR, FINE_DB_CEIL)
      by = math.max(y0+4, math.min(y0+h-4, by))
      -- Hover detection (8px radius)
      local hovered = (mx >= bx-8 and mx <= bx+8 and my >= by-8 and my <= by+8)
      local col = hovered and 0xFFE066FF or 0xFFBF24CC
      -- Diamond handle
      ImGui.DrawList_AddQuadFilled(dl, bx, by-7, bx+7, by, bx, by+7, bx-7, by, col)
      ImGui.DrawList_AddQuad(dl, bx, by-7, bx+7, by, bx, by+7, bx-7, by, 0xFFFFFFAA, 1.0)
      -- Frequency label
      local fl = band.freq_hz >= 1000
             and string.format('%.1fk', band.freq_hz/1000)
             or  string.format('%.0f', band.freq_hz)
      ImGui.DrawList_AddText(dl, bx-14, by+9, 0xFFE066CC, fl)
      -- Gain readout on hover
      if hovered then
        local gl = string.format('%+.1f dB', band.gain_db)
        ImGui.DrawList_AddRectFilled(dl, bx-22, by-22, bx+22, by-10, 0x000000CC, 3)
        ImGui.DrawList_AddText(dl, bx-18, by-20, 0xFFFFFFFF, gl)
      end
      -- Drag-to-adjust gain (left mouse, not Alt)
      if hovered and ImGui.IsMouseClicked(ctx, 0) and not is_alt then
        state._bridge_drag_band   = band
        state._bridge_drag_start_y  = my
        state._bridge_drag_start_db = band.gain_db
        state._bridge_drag_entry    = bridge._active_entry
      end
    end
    -- Process active drag
    if state._bridge_drag_band and ImGui.IsMouseDown(ctx, 0) then
      local dy_px = my - (state._bridge_drag_start_y or my)
      local dy_db = -(dy_px / h) * (FINE_DB_CEIL - FINE_DB_FLOOR)
      local new_db = (state._bridge_drag_start_db or 0) + dy_db
      new_db = math.max(-36, math.min(36, new_db))
      state._bridge_drag_band.gain_db = new_db
      if bridge.set_band_gain and state._bridge_drag_entry then
        bridge.set_band_gain(state._bridge_drag_entry, state._bridge_drag_band, new_db)
      end
    elseif not ImGui.IsMouseDown(ctx, 0) then
      state._bridge_drag_band = nil
    end
  end
end

-- ============================================================================
-- Broad Mode -- ASCII-safe, no mojibake
-- ============================================================================
local BROAD_BANDS_META = {
  { name = "Sub",     range = "20-60 Hz",   col = 0xF472B6FF, fill = 0xF472B61A, border = 0xF472B688 },
  { name = "Bass",    range = "60-250 Hz",  col = 0x818CF8FF, fill = 0x818CF81A, border = 0x818CF888 },
  { name = "Low Mid", range = "250-2k Hz",  col = 0x34D399FF, fill = 0x34D3991A, border = 0x34D39988 },
  { name = "High",    range = "2k-20k Hz",  col = 0xFBBF24FF, fill = 0xFBBF241A, border = 0xFBBF2488 },
}
local CREST_ZONES = {
  { lo = 0,  hi = 8,  col = 0xEF444422, label = "Compressed"  },
  { lo = 8,  hi = 14, col = 0x22D3EE28, label = "Punchy [OK]" },
  { lo = 14, hi = 20, col = 0xFBBF2422, label = "Dynamic"     },
  { lo = 20, hi = 24, col = 0xF9731622, label = "Extreme"     },
}

function VIEW.draw_broad(ctx, ImGui, dl, x0, y0, w, h, state, tgt_broads)
  local DB_RANGE = 12.0
  local midline  = y0 + h * 0.5

  ImGui.DrawList_AddRectFilled(dl, x0, y0, x0+w, y0+h, 0x0D1117FF, 6)
  ImGui.DrawList_AddRect(dl, x0, y0, x0+w, y0+h, C.border, 6)
  ImGui.DrawList_AddLine(dl, x0+4, midline, x0+w-4, midline, C.zero_line, 1)

  for db = -12, 12, 6 do
    local ty = midline - (db / DB_RANGE) * (h * 0.5)
    ImGui.DrawList_AddLine(dl, x0, ty, x0+4, ty, C.grid_line, 1)
    ImGui.DrawList_AddText(dl, x0-26, ty-6, C.grid_label, string.format("%+d", db))
  end

  local band_w = w / 4
  for i = 1, 4 do
    local meta = BROAD_BANDS_META[i]
    local bx   = x0 + (i-1) * band_w
    local rms  = math.max(-DB_RANGE, math.min(DB_RANGE, state.broad[i] or 0))
    local tgt  = tgt_broads and tgt_broads[i] or { target=0, upper=3, lower=-3 }

    -- Corridor shaded zone
    local hi_y = math.max(y0+4,   midline - (tgt.upper/DB_RANGE) * (h*0.5))
    local lo_y = math.min(y0+h-4, midline - (tgt.lower/DB_RANGE) * (h*0.5))
    ImGui.DrawList_AddRectFilled(dl, bx+4, hi_y, bx+band_w-4, lo_y, meta.fill, 4)
    local tc_y = midline - (tgt.target/DB_RANGE) * (h*0.5)
    ImGui.DrawList_AddLine(dl, bx+6, tc_y, bx+band_w-6, tc_y, meta.border, 2)

    -- Live bar
    local bar_h = math.abs(rms) / DB_RANGE * (h*0.5)
    local bar_t = rms >= 0 and (midline - bar_h) or midline
    local bar_b = rms >= 0 and midline or (midline + bar_h)
    bar_t = math.max(y0+4, bar_t); bar_b = math.min(y0+h-4, bar_b)
    local dev   = rms - tgt.target
    local bar_col = math.abs(dev) < 3.0 and (meta.col & 0xFFFFFFCC)
                  or (math.abs(dev) < 6.0 and (C.warn | 0xFF) or (C.danger | 0xFF))
    if bar_t < bar_b then
      ImGui.DrawList_AddRectFilled(dl, bx+12, bar_t, bx+band_w-12, bar_b, bar_col, 3)
    end

    -- Delta readout + labels (clean ASCII only)
    local delta_col = math.abs(dev) < (tgt.upper - tgt.target) and C.text
                    or (dev > 0 and C.ok or C.warn)
    ImGui.DrawList_AddText(dl, bx+band_w/2-18, y0+8,    delta_col,   string.format("%+.1f dB", dev))
    ImGui.DrawList_AddText(dl, bx+6,           y0+h-24, C.text_muted, meta.name)
    ImGui.DrawList_AddText(dl, bx+6,           y0+h-12, 0x4E5766FF,   meta.range)

    -- Band separator
    if i < 4 then
      ImGui.DrawList_AddLine(dl, bx+band_w, y0+8, bx+band_w, y0+h-8, C.border, 1)
    end

    -- Solo click detection
    local mx, my = ImGui.GetMousePos(ctx)
    if mx >= bx and mx < bx+band_w and my >= y0 and my < y0+h then
      if ImGui.IsMouseClicked(ctx, 0) then
        state.solo = (state.solo == i) and 0 or i
        reaper.gmem_write(472, state.solo)
      end
    end
    if state.solo == i then
      ImGui.DrawList_AddRect(dl, bx+1, y0+1, bx+band_w-1, y0+h-1, 0xD4A24CEE, 0, 0, 2)
      ImGui.DrawList_AddText(dl, bx+8, y0+8, 0xD4A24CFF, "[SOLO]")
    end
  end

  -- Offline fallback (clean ASCII, uses active_binding_name from tbc.lua)
  if not state.engine_alive then
    local msg = state.active_binding_name
      and ("Listening to: " .. tostring(state.active_binding_name) .. " -- waiting for audio...")
      or "[!] No TonalBalance found -- use [+ Insert] button to add on selected track."
    ImGui.DrawList_AddText(dl, x0+10, y0+h/2-8, C.warn, msg)
  end
end

function VIEW.draw_crest_needle(dl, x0, y0, w, h, crest_db)
  local CF_MIN, CF_MAX = 0, 24
  local crest = math.max(CF_MIN, math.min(CF_MAX, crest_db or 8))
  local norm  = (crest - CF_MIN) / (CF_MAX - CF_MIN)
  local nx    = x0 + norm * w

  ImGui.DrawList_AddRectFilled(dl, x0, y0, x0+w, y0+h, C.surface, 4)
  ImGui.DrawList_AddRect(dl, x0, y0, x0+w, y0+h, C.border, 4)

  for _, z in ipairs(CREST_ZONES) do
    local zx0 = x0 + (z.lo / CF_MAX) * w
    local zx1 = x0 + (z.hi / CF_MAX) * w
    ImGui.DrawList_AddRectFilled(dl, zx0, y0+4, zx1, y0+h-4, z.col, 0)
    ImGui.DrawList_AddText(dl, zx0+4, y0+4, 0xFFFFFF40, z.label)
  end

  for cf = 0, 24, 2 do
    local tx   = x0 + (cf/24)*w
    local th_n = cf % 6 == 0 and 0.45 or 0.2
    ImGui.DrawList_AddLine(dl, tx, y0+h*(1-th_n), tx, y0+h, 0xFFFFFF50, 1)
    if cf % 6 == 0 then
      ImGui.DrawList_AddText(dl, tx-5, y0+h-th_n*h-14, C.grid_label, tostring(cf))
    end
  end

  local ncol = (crest < 8)  and C.danger
             or (crest < 14) and C.ok
             or (crest < 20) and C.warn
             or 0xF97316FF
  ImGui.DrawList_AddLine(dl, nx, y0, nx, y0+h, ncol, 3)
  ImGui.DrawList_AddTriangleFilled(dl, nx-5, y0, nx+5, y0, nx, y0+9, ncol)

  local lbl = (crest < 8)  and "OVER-COMPRESSED"
           or (crest < 14) and "PUNCHY [OK]"
           or (crest < 20) and "DYNAMIC"
           or "VERY TRANSIENT"
  ImGui.DrawList_AddText(dl, nx+10, y0+h/2-7, ncol, string.format("%.1f dB  %s", crest, lbl))
end

