-- Called by both standalone window and console tab.
-- state fields: view_mode, genre, broad[4], display_bins[256],
--               engine_alive, crest_low, eq_visible
-- Test 5: 60fps render rate cap for high-refresh monitors
local _last_render_t = 0
local _render_min_dt = 0.0166
function VIEW.render(ctx, ImGui, state, TGT, BRIDGE)
  local dl   = ImGui.GetWindowDrawList(ctx)
  local _now = reaper.time_precise()
  if (_now - _last_render_t) < _render_min_dt then return end
  _last_render_t = _now

  local avw, avh = ImGui.GetContentRegionAvail(ctx)
  local cx, cy   = ImGui.GetCursorScreenPos(ctx)
  local cw       = avw - 4

  local canvas_h = math.max(160, avh - 80)
  local needle_h = 44

  local curve = TGT and TGT.get_target(state.genre) or nil
  local tgt_b = TGT and TGT.get_broad_targets(state.genre) or nil

  if state.view_mode == "Fine" then
    ImGui.Dummy(ctx, cw, canvas_h)
    VIEW.draw_fine(ctx, ImGui, dl, cx, cy, cw, canvas_h, state, curve, BRIDGE)
  else
    ImGui.Dummy(ctx, cw, canvas_h)
    VIEW.draw_broad(ctx, ImGui, dl, cx, cy, cw, canvas_h, state, tgt_b)
  end

  ImGui.Spacing(ctx)
  ImGui.Separator(ctx)
  ImGui.Text(ctx, "Low-End Dynamics  20-250 Hz")
  ImGui.SameLine(ctx, 0, 8)
  ImGui.TextDisabled(ctx, string.format("%.1f dB crest", state.crest_low or 8))

  local nx2, ny2 = ImGui.GetCursorScreenPos(ctx)
  ImGui.Dummy(ctx, cw, needle_h)
  VIEW.draw_crest_needle(dl, nx2, ny2, cw, needle_h, state.crest_low or 8)
end

return VIEW

